-- ============================================================
-- Oklahoma Repeater Coordination System
-- Database Schema + Seed Data
-- Compatible with MySQL 5.7+ / MariaDB 10.3+
-- ============================================================

CREATE DATABASE IF NOT EXISTS ok_repeater_coord
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ok_repeater_coord;

-- ============================================================
-- REPEATERS TABLE
-- ============================================================
CREATE TABLE IF NOT EXISTS repeaters (
  id               INT AUTO_INCREMENT PRIMARY KEY,
  district         VARCHAR(10)  NOT NULL DEFAULT '',
  type             VARCHAR(20)  NOT NULL DEFAULT 'REPEATER',
  status           VARCHAR(30)  NOT NULL DEFAULT 'PROPOSED',
  output_freq      DECIMAL(9,4) NOT NULL,
  input_freq       DECIMAL(9,4) NOT NULL,
  callsign         VARCHAR(20)  NOT NULL DEFAULT '',
  trustee          VARCHAR(15)  NOT NULL DEFAULT '',
  sponsor          VARCHAR(100) NOT NULL DEFAULT '',
  county           VARCHAR(50)  NOT NULL DEFAULT '',
  city             VARCHAR(60)  NOT NULL DEFAULT '',
  pl_tone          DECIMAL(6,1) DEFAULT NULL,
  open_system      TINYINT(1)   NOT NULL DEFAULT 1,
  autopatch        TINYINT(1)   NOT NULL DEFAULT 0,
  closed_autopatch TINYINT(1)   NOT NULL DEFAULT 0,
  skywarn          TINYINT(1)   NOT NULL DEFAULT 0,
  linked           TINYINT(1)   NOT NULL DEFAULT 0,
  internet_link    VARCHAR(50)  NOT NULL DEFAULT '',
  date_coordinated DATE         DEFAULT NULL,
  last_update      DATE         DEFAULT NULL,
  url              VARCHAR(255) NOT NULL DEFAULT '',
  notes            TEXT,
  latitude         DECIMAL(9,6) DEFAULT NULL,
  longitude        DECIMAL(9,6) DEFAULT NULL,
  created_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_output  (output_freq),
  INDEX idx_district (district),
  INDEX idx_status   (status),
  INDEX idx_callsign (callsign),
  INDEX idx_type     (type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- COORDINATION RULES TABLE
-- ============================================================
CREATE TABLE IF NOT EXISTS coordination_rules (
  id                      INT AUTO_INCREMENT PRIMARY KEY,
  rule_name               VARCHAR(100) NOT NULL,
  band_low_mhz            DECIMAL(9,4) NOT NULL COMMENT 'Lower bound of band in MHz',
  band_high_mhz           DECIMAL(9,4) NOT NULL COMMENT 'Upper bound of band in MHz',
  channel_step_khz        DECIMAL(8,3) NOT NULL COMMENT 'Allowed channel step in kHz',
  channel_width_khz       DECIMAL(8,3) NOT NULL COMMENT 'Max channel width / bandwidth in kHz',
  co_channel_min_miles    DECIMAL(8,2) NOT NULL DEFAULT 75.00 COMMENT 'Min distance between co-channel repeaters (miles)',
  adj_channel_min_miles   DECIMAL(8,2) NOT NULL DEFAULT 50.00 COMMENT 'Min distance between adjacent-channel repeaters (miles)',
  notes                   TEXT,
  created_at              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- COORDINATION CONFLICTS TABLE
-- ============================================================
CREATE TABLE IF NOT EXISTS coordination_conflicts (
  id              INT AUTO_INCREMENT PRIMARY KEY,
  repeater_a_id   INT NOT NULL,
  repeater_b_id   INT NOT NULL,
  conflict_type   ENUM('CO_CHANNEL','ADJACENT_CHANNEL') NOT NULL,
  distance_miles  DECIMAL(8,2) DEFAULT NULL,
  freq_diff_khz   DECIMAL(8,3) DEFAULT NULL,
  resolved        TINYINT(1) NOT NULL DEFAULT 0,
  resolution_note TEXT,
  detected_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at     TIMESTAMP DEFAULT NULL,
  FOREIGN KEY (repeater_a_id) REFERENCES repeaters(id) ON DELETE CASCADE,
  FOREIGN KEY (repeater_b_id) REFERENCES repeaters(id) ON DELETE CASCADE,
  INDEX idx_resolved (resolved),
  INDEX idx_type (conflict_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- USERS TABLE
-- ============================================================
CREATE TABLE IF NOT EXISTS users (
  id           INT AUTO_INCREMENT PRIMARY KEY,
  username     VARCHAR(50)  NOT NULL UNIQUE,
  password     VARCHAR(255) NOT NULL COMMENT 'bcrypt hash',
  email        VARCHAR(150) NOT NULL DEFAULT '',
  callsign     VARCHAR(20)  NOT NULL DEFAULT '',
  role         ENUM('admin','coordinator','viewer') NOT NULL DEFAULT 'viewer',
  active       TINYINT(1)   NOT NULL DEFAULT 1,
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login   TIMESTAMP    DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- AUDIT LOG TABLE
-- ============================================================
CREATE TABLE IF NOT EXISTS audit_log (
  id           INT AUTO_INCREMENT PRIMARY KEY,
  user_id      INT DEFAULT NULL,
  action       VARCHAR(50)  NOT NULL,
  table_name   VARCHAR(50)  NOT NULL,
  record_id    INT DEFAULT NULL,
  old_data     JSON DEFAULT NULL,
  new_data     JSON DEFAULT NULL,
  ip_address   VARCHAR(45)  DEFAULT NULL,
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_table_record (table_name, record_id),
  INDEX idx_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

